import Foundation
struct U: Decodable { var nick: String? }
let d = Data("{}".utf8)
let u = try JSONDecoder().decode(U.self, from: d)
print(u.nick ?? "none")
// String? uses decodeIfPresent

import Foundation
let d = JSONDecoder()
d.dateDecodingStrategy = .iso8601
let j = Data("\"2024-01-01T00:00:00Z\"".utf8)
